    "text": "Das Fahrrad: ernsthafte Konkurrenz fürs Auto?\n\nWelches Fortbewegungsmittel, denken Sie, wird in Deutschland am häufigsten benutzt? Natürlich das Automobil. Volkswagen, Porsche, Mercedes Benz, BMW, Audi: in .....(1)..... einem anderen Land gibt es so viele Automobilfabriken wie in Deutschland, spielt die Automobilindustrie eine so große Rolle. Nahezu jeder Haushalt verfügt über mindestens ein Auto, das Auto spielt im Leben der Deutschen eine große Rolle, sowohl als Fortbewegungsmittel zum Arbeitsplatz oder in den Urlaub als auch als Statussymbol: Zeig mir dein Auto und ich weiß, wer du bist.\n\nDoch hat das Autofahren auch Schattenseiten. Mangelnde Bewegungsmöglichkeiten, gesundheitliche Probleme und Stress bringen zumindest in den Großstädten immer mehr Autofahrer dazu, sich vom Automobil freizumachen und .....(2)..... ein anderes Verkehrsmittel umzusteigen, das in dem Ruf steht, gesünder zu sein als das Auto: das Fahrrad. Nicht nur in der Freizeit, sondern auch auf dem Weg zum Arbeitsplatz wird das Rad benutzt. “Ich habe keine Lust, Morgen für Morgen im Stau zu stehen und Zeit zu verlieren”, sagt Bettina Meier 25. “Da ist es viel entspannter, auf den zumeist gut ausgebauten Fahrradwegen an den im Stau wartenden Fahrzeugen .....(3)..... und ausgeruht am Arbeitsplatz anzukommen.”\n\nDass Fahrradfahren um einiges gesünder ist, als hinter dem Lenkrad zu sitzen, bestätigen auch die Mediziner. Wer Fahrrad fährt .....(4)..... zu sitzen, bringt seinen Blutkreislauf in Schwung, stärkt die Abwehrkräfte des Körpers und trainiert seinen Körper. Auch die Bewegung an der frischen Luft tut Menschen gut, die sich sonst die meiste Zeit .....(5)..... geschlossener Räume in Büros, Schulen oder Fabriken aufhalten .....(6)......\n\nAuch die Geschäftswelt hat die Fahrradfahrer als Kunden entdeckt. Ein breites Angebot .....(7)..... Zubehör für Fahrräder von schicken Radfelgen über sportliche Mehrganggetriebe, mit denen Berge kein Problem mehr darstellen, bis zur Designer-Trinkflasche machen aus dem einfachen Fahrrad ein exklusives Fahrzeug. Und natürlich darf bei keinem Fahrradfahrer eine aufwändige Sicherheitsausstattung mehr fehlen: Schutzhelme, Ellenbogen- und Knieschützer, die das Fahrrad im Falle eines Unfalls fast so sicher wie einen Panzer machen .....(8)......\n\nNur wenn es regnet – und das passiert in Deutschland leider nicht so selten –, .....(9)..... sind die Autoschlangen wieder länger. .....(10)..... einen praktischen Wetterschutz für Radfahrer haben die Geschäfte noch nicht im Angebot.",
