        "c": "zum",
        "explain": "التعبير 'zum Kochlöffel greifen' يعني 'يمسك بملعقة الطهي'؛ 'zum' اختصار لـ 'zu dem' مع الاسم المذكر (der Kochlöffel).",
        "mod": true
