    "text": "Klimatische Veränderungen seit der letzten Kaltzeit könnten für den stetigen Rückgang der Braunbären zahl in Europa verantwortlich sein. wie eine aktuelle Studie nahelegt, haben vor allem steigende Wintertemperaturen .....(1)..... der vergangen 12000Jahre die Fortpflanzungsrate der Tiere verringert, was entscheidend zu deren Verschwinden beigetragen hat. Zudem wurden durch die Klimaveränderung größere Flächen für den Ackerbau nutzbar. .....(2)..... wurde der Lebensraum der Tiere verkleinert. Es ist längst unumstriten, .....(3)..... das Verschwinden der der Braunbären mit der Landnutzung durch den Menschen zusammenhängt .\n\nEin internationales Experten Team untersuchte nun die Rolle des Klimas beim Rückgang der Bären zahl. In den letzten Jjahren ist Winter Temperatur in weiten Teilen Europas .....(4)..... zwei bis vier Grad angestiegen. In der Folge bekamen die Braunbären weniger .....(5)..... , und ihre Zahl schrumpfte. Der Grund .....(6)..... ist, dass Braunbären bei steigenden Wintertemperaturen in mehr Energie für ihre Winterruhe verbrauchen. Braunbärenweibchen benötigen ihre Enrergie reserven auch für die Fortpflanzung , .....(7)..... sie bringen im Winter ihre Jungen zur Welt. Wird mehr Energie für die Winterruhe verbraucht , bleibt nicht so viel für die Fortpflanzung übrig , und gibt es weniger Nachwuchs .\n\nsteigende Wintertemperaturen könnten auch in direkt für das Schicksal des Braunbären wortlich gewesen sein. Wärmer Winter begünstigten nämlich auch die menschlicher .....(8)..... in die Naturlandschaften und damit in den Lebensraum der Braunbären. Am Ende der letzten Eiszeit war der Braunbär .....(9)..... überall in Europa heimlich großes Aussterben gab es in Südwesteuropa vor 70 7 bis 0 Jjahren. Richtig begrab .....(10)..... es mit dem Braunbären aber vor etwa jahre, als sich verringerte .",
