    "text": "Kinder sind oft mit dem Straßenverkehr überfordert, .....(1)..... ist  es wichtig, dass sich Eltern und Bezugspersonen den besten Schulweg überlegen und mit ihren Kindern üben. .....(2)..... Immer ist der kürzeste Weg auch der ungefährlichste. Zum Üben sollte man sich Zeit nehmen und sich voll auf das Kind .....(3)...... Eltern sollten im Verkehr immer auch an ihre Vorbildfunktion denken: Verkehrsregeln nicht nur erklären, sondern sich auch .....(4)..... daran halten. Wegen ihrer geringeren Körpergröße haben Kinder ein anderes Sichtfeld als Erwachsene. Dessen müssen sich die Erwachsenen bewusst sein. Manchmal ist es .....(5)....., wenn die Großen sich von ihren Kindern erzählen lassen, was diese sehen Um das Kind langsam an den Schulweg zu gewöhnen, sollte es anfangs nur das letzte Stück allein gehen. Diese Strecke kann man dann Schritt .....(6)..... Schritt verlängern. Dasselbe gilt für den Nachhauseweg. Auch ist es sinnvoll, zu Schulbeginn nochmals kurz und klar die wichtigsten Regeln für das .....(7)..... im Straßenverkehr mit den Kindem zu wiederholen. Wenn der Schulweg kein Problem mehr darstellt, kann man noch mögliche .....(8)..... Situationen besprechen. Wie zum Beispiel „Was machst du, wenn der Gehweg gespert ist?“ oder Was tust du, wenn die Ampel ausgefallen ist? oder Was machst du, wenn auf der anderen Straßenseite jemand nach dir ruft oder jemand bei Rot über die Kreuzung rennt?\". So lernt das Kind, sich .....(9)..... im Straßenverkehr zu verhalten und selbstständig .....(10)..... zu finden. Und die Erwachsenen können sicher sein, dass ihr Kind zumindest auf die Standardsituationen vorbereitet ist.",
