    "text": "Fische sind dumm, stumm und haben keine Empfindungen – diese Vorurteile halten sich hartnäckig. Doch .....(1)..... das Gegenteil ist der Fall. Sie sind nämlich zu erstaunlichen kognitiven Leistungen .....(2)..... und können sowohl Freude als auch Schmerz empfinden. Die meisten Menschen wüssten so gut wie nichts über Fische, beklagt der Verhaltensbiologe Douglas Allan. Wenn man genauer hinsehe, verändere sich aber die Sicht auf sie.\n\nDenn das Leben im Wasser stellt die etwa 33.000 existierenden Arten vor besondere Herausforderungen. Im Laufe der Zeit .....(3)..... sie hochspezialisierte Sinnesfähigkeiten und Kommunikationsformen. So verständigen sie sich über Geräusche, Gerüche oder Berührungen. Einige Arten lernen durch .....(4)..... oder benutzen sogar Werkzeuge.\n\nBis in die 1930er Jahre wurde Fischen .....(5)..... nicht einmal zugetraut, dass sie hören können. Erst dem österreichischen Verhaltensforscher Karl von Frisch gelang der Nachweis: Er brachte seinem blinden Wels Xaverl bei, auf ein akustisches Signal zu reagieren. Wenn er pfiff, kam Xaverl aus seinem Versteck, um Futter in Empfang zu nehmen. Der Forscher bewies .....(6)..... auch als Erster, dass Fische Farben sehen können.\n\n.....(7)..... warum wurden die Fähigkeiten der Fische so lange unterschätzt? „.....(8)..... intelligent halten wir oft nur Tiere, die uns ähnlich sind“, erklärt Douglas Allan. Fische hätten daher schlechte Karten. Schließlich müssten sie mit ganz anderen Lebensbedingungen zurechtkommen .....(9)..... Tiere an Land. Allan rät, .....(10)..... mehr über Fische herausfinden wolle, solle einfach mal in einem Aquarium im Zoo ein paar Minuten lang einen einzelnen Fisch beobachten. Dann erkenne man schnell, dass Fische nicht nur ein Bewusstsein, sondern auch einen eigenen Charakter und Bedürfnisse hätten.",
