    "text": "Die gelernte Krankenschwester Jaqueline Delgado drückt mit 38 Jahren noch einmal die Schulbank. .....(1)....., sie hat sich für einen beruflichen Neustart entschieden. Da ihr früherer Beruf ihr keinen Spaß mehr machte, begann sie eine Berufsausbildung bei der Polizei. Ihr Ziel: Sie .....(2)..... in den Streifendienst gehen.\n\nMit über 30 noch einmal einen ganz neuen Job zu erlernen - lange Zeit war das kaum möglich. Arbeitgeber suchten nur junge Berufseinsteiger. .....(3)..... es heute in vielen Branchen aber an Nachwuchs fehlt, geben sie öfter auch Älteren eine .....(4)..... .\n\nThomas Neuendorfer, der stellvertretende Sprecher der Polizei Berlin, erklärt, .....(5)....., sein Arbeitgeber gerne Ältere ausbildet: \"Sie haben in ihrem Berufsleben Erfahrungen gesammelt, die der Polizei und auch den Bürgern der Stadt zu Gute kommen\". Sie seien häufig emotional reifer, außerdem bereit, Verantwortung zu .....(6)....., und motiviert, die Ausbildung erfolgreich abzuschließen. Zudem .....(7)..... sie die Jüngeren unterstützen und ihnen als Vorbild dienen. Davon profitieren dann auch die Arbeitgeber. Gegen die Einstellung von Älteren spreche nur, dass sie dem Unternehmen kürzer vor .....(8)..... stehen. .....(9)..... haben ältere Azubis in vielen Bereichen Möglichkeiten: in kaufmännischen oder in gewerblich-technischen Berufen, im Gesundheitswesen oder vor allem in der Gastronomie.\n\nWenn das Azubi-Gehalt nicht für den Lebensunterhalt reicht, hilft die Arbeitsagentur. Der Betrag wird dabei nicht nach dem Alter festgelegt, .....(10)..... es wird der individuelle, konkrete Bedarf ermittelt. Im August schließt Delgado ihre Ausbildung ab. In dem künftigen Polizei-Job wird sie ihr medizinisches Wissen, ihre Menschenkenntnis sowie ihre spanischen und englischen Sprachkenntnisse wohlgut gebrauchen können.",
