    "text": "Höflichkeit gehört zu den Dingen, die allmählich verschwinden.“ Drei von vier Deutschen .....(1)..... Dieser Behauptung zu: Früher waren die Menschen höflicher, .....(2)..... einer Umfrage zufolge 75 Prozent der Befragten. Genauso viele denken, dass junge Leute zu wenig Respekt vor älteren Menschen haben.\n\nÄrgert sich da möglicherweise nur die ältere Generation über den Verlust überholter Umgangsformen? Keineswegs: Glaubt man der Studie, besteht der Wunsch .....(3)..... gewissen Höflichkeitsformen altersübergreifend.\n\nKlare Spielregeln für ein höfliches .....(4)..... – In einer immer weniger von Formalität und offiziellen Hierarchien geprägten Welt sucht man sie oft .....(5)..... – Da wäre zum Beispiel die Frage nach dem Du oder Sie. .....(6)..... die Hälfte der Deutschen gibt zu, regelmäßig verunsichert zu sein, wie sie ihr Gegenüber ansprechen sollen. Während es jüngere Menschen zum Beispiel als normal oder sogar angenehm empfinden .....(7)....., vom Kellner geduzt zu werden, kann es älteren Semestern den Restaurantbesuch vermiesen. Nur ein Viertel der Befragten kann sich damit anfreunden, besonders Ältere .....(8)..... – sich am ungefragten Duzen.\n\nÜber andere Umgangsformen herrscht hingegen Konsens bei Jung und Alt: Den Sitzplatz in der Bahn Älteren oder Schwangeren anzubieten, finden 94 Prozent wichtig. 95 Prozent legen Wert auf Pünktlichkeit. Für immerhin 78 Prozent erfordert es die Höflichkeit, dass Männer Frauen die Tür aufhalten und ihnen den Vortritt .....(9)..... . Unhöflich finden es 91 Prozent, wenn jemand während einer Unterhaltung auf das Handy schaut.\n\nAngesichts von so viel Einigkeit über den angemessenen Umgang miteinander stellt sich freilich die Frage, warum so wenig davon im Alltag zu sehen ist. Wenn man weiß, was .....(10)..... gehört, kann es doch nicht so schwer sein, sich daran zu halten.",
