    "text": "Maßgeschneidert nach Bodyscanning\n\nHaben Sie sich schon einmal .....(1)..... aufgeregt, dass Sie zwar in vielen Geschäften viele schöne Kleidungsstücke sehen konnten, Ihnen aber dann bei der Anprobe keines gepasst hat? Dann geht es Ihnen wie zurzeit der Mehrheit der deutschen Bevölkerung: Die Kleidungsstücke, die in den Modehäusern angeboten werden, gibt es fast .....(2)..... noch in den falschen Größen.\n\nEine Untersuchung des Textilforschungszentrums Hohenstein .....(3)..... nun zu der folgenden Erkenntnis: Der Grund dafür, dass viele Konfektionsgrößen offenbar .....(4)..... den Kundinnen noch den Kunden passen, sei die körperliche Entwicklung der Bevölkerung in Deutschland. Seit den 1960er Jahren seien die Deutschen im Durchschnitt um bis zu acht Zentimeter sowohl größer als auch dicker geworden.\n\nDie Länge der Arme .....(5)..... zugenommen, besonders aber an den Hüften hätten die Deutschen beträchtlich zugelegt.\n\n.....(6)..... man natürlich daran interessiert ist, Kleidungsstücke in den richtigen Größen und in ausreichender Zahl zu produzieren, soll jetzt ein neu ermittelt werden, welche Größen die Kunden eigentlich brauchen. Dazu wurde ein neues Verfahren entwickelt, .....(7)..... Männer und Frauen neu vermessen soll. Bei der Body-Scan-Technologie tasten mehrere Kameras mit Laserlicht die menschlichen Körper ab und erstellen ein dreidimensionales Ebenbild der gescannten Person. Diese dreidimensionalen Bilder .....(8)..... es ermöglichen, in Zukunft genauere Informationen über die durchschnittliche Körpergröße zu erhalten.\n\nÄhnliche Messungen werden auch in Großbritannien, den Niederlanden, den skandinavischen Ländern, Frankreich und den USA vorgenommen. Mehr als zwei Millionen Euro wollen die Modefirmen dafür investieren, das Ergebnis lohnt sich aber für sie auf jeden Fall.\n\nAls Kundinnen und Kunden dürfen wir uns außerdem darauf freuen, .....(9)..... sich als Nebenprodukt der Körpervermessung in den verschiedenen Ländern die Modefirmen vielleicht endlich dafür entscheiden, weltweit gleiche Nummern für gleiche Größen einzuführen. Dann ist ein Kleidungsstück mit der Nummer 36 überall .....(10)..... groß, ob in Nord- oder Südeuropa, in Amerika oder Asien.",
