    "text": "Es ist erst 6 Uhr morgens, und draußen herrscht noch Dunkelheit.....(1).....in der riesigen, hell erleuchteten Halle, in der sich Kisten mit Obst und Gemüse meterhoch stapeln, wird schon lange gearbeitet. Vor ein paar Stunden war hier noch viel mehr Betrieb », sagt Jens Rogall. Er .....(2)..... einen Berliner Großmarkt, auf dem Einkäufer von Supermärkten, Geschäften oder Restaurants frisches Obst und Gemüse besorgen.\n\nDie Ware hat oft schon eine lange Reise zurückgelegt, bis sie auf dem Großmarkt .....(3)..... . Die meisten Früchte werden .....(4)..... auf dem Land-, Luft- oder Seeweg aus wärmeren Ländern nach Deutschland transportiert. Wenn die Ware per Schiff nach Europa gebracht wird, kommt sie in großen Seehäfen wie Rotterdam oder Hamburg an. Von dort aus geht es mit dem Lastwagen weiter. Auf seinem Weg .....(5)..... das empfindliche Obst und Gemüse keinesfalls Schaden nehmen. ,, Nichts ist schlimmer .....(6)..... verdorbene Ware », sagt Rogall.\n\nAuf dem Großmarkt schauen sich die Käufer alles .....(7)..... an. Für makellose Salatköpfe, Beeren und Kräuter zahlen sie höhere Preise, krumme Gurken oder verwachsene Kartoffeln .....(8)..... sie dagegen günstiger. Diese werden später nicht in Geschäften zum Verkauf angeboten, .....(9)..... direkt verarbeitet. ,,Es ist egal, wie Gurken aussehen, die ohnehin im Fertigsalat landen », erklärt Rogall. Wenn die Preisverhandlungen erfolgreich .....(10)..... sind, werden die Paletten voller Obst und Gemüse hinaus zu den Lieferwagen gebracht. Die Fahrer müssen dann zügig zu den Geschäften und Restaurants fahren, um die Ware abzuliefern.",
