    "text": "Sitz, Platz, Pfötchen geben: Nur die wenigsten Katzen befolgen Kommandos. Dabei sind sie durchaus in der .....(1)....., ihren Namen aus anderen Wörtern herauszuhören, berichtet ein japanisches Forschungsteam im Fachblatt \"Scientific Reports\". Nach eigenen .....(2)..... haben sie den ersten experimentellen Nachweis geliefert, dass Katzen Laute von Menschen verstehen können. Erst als ihnen ihr eigener Name vorgespielt wurde, zeigten die meisten Versuchstiere eine Reaktion. Sie bewegten beispielsweise ihre Ohren oder drehten den Kopf. Der Effekt war auch zu beobachten, wenn nicht der Katzenbesitzer selbst zu seinem Tier sprach, .....(3)..... eine fremde Person. Lebten mehrere Katzen in einem Haushalt, konnten einige Katzen ihren Namen von .....(4)..... ihrer Artgenossen unterscheiden. Die Forscher hatten das .....(5)..... von 78 Katzen untersucht. .....(6)..... spielten sie den Tieren vier japanische Wörter vom Band vor, die ähnlich klangen wie der Name der Katze. Dabei nahm die Aufmerksamkeit der Katzen immer .....(7)..... ab. Doch wenn die Tiere ihren Namen und einzelne Gesten verstehen, warum ist es .....(8)..... schwierig, ihnen Tricks beizubringen? Laut Turner sei dies durchaus möglich, allerdings verlören die meisten Halter schnell die Geduld. Biologe Dennis Turner hält die japanische Studie für 'seriös durchgeführt'. Die Ergebnisse aus Japan seien sicher auch auf deutsche Katzen übertragbar, so Turner. \"Ich er ist er von dem Ergebnis allerdings nicht. \"Katzen sind sehr intelligente und lernfähige Tiere- .....(9)..... sie bereit sind mitzumachen\", sagt Turner, der nicht an der Studie beteiligt war. Aus vorherigen Untersuchungen ist .....(10)....., dass es Katzen verstehen, wenn Menschen mit dem Finger den Weg zum Fressnapf zeigen. Zudem ändern zumindest einige Katzen ihr Verhalten, je nachdem, ob ihr Herrchen grimmig oder fröhlich schaute.",
