    "text": "Zu Hause bequem vor dem Fernseher sitzen und einkaufen – das hört sich doch gut an! Gut schon – aber ist es auch günstig?\n\nDie Stiftung Warentest hat sich im Interesse der Kundinnen und Kunden drei große Anbieter einmal genauer angeschaut: Qualität .....(1)..... enttäuschend, Preise ziemlich hoch, rechtliche Rahmenbedingungen und Service im Wesentlichen in Ordnung, Werbung grell und nervig – so etwa lautet das Fazit, das die Stiftung Warentest zum Thema Teleshopping nach dem Test von drei großen Anbietern .....(2)......\n\nGenau wie die Stiftung Warentest sind auch die Verbraucherzentralen auf der Seite der Kunden. Die Juristin der sächsischen Verbraucherzentrale, Bettina Dittrich, meint zu der Untersuchung von Stiftung Warentest: „Das deckt sich im Wesentlichen mit den Erfahrungen, die wir .....(3)..... Beschwerdefällen machen“, und ergänzt, „doch nicht immer und überall läuft es damit problemlos.“\n\nGegenwärtig beschäftigen sie mehrere Beschwerden von Verbrauchern, die bei einem ausländischen Teleshoppinganbieter eingekauft hatten. Da wird für fristgerecht zurückgesandte Waren der Kaufpreis nicht erstattet, .....(4)..... es erfolgt nur eine Gutschrift – und das nicht einmal in voller .....(5)...... Dabei beruft man sich offenbar auf die geltenden Allgemeinen Geschäftsbedingungen. Zumindest werden diese teilweise der Warenlieferung mitgeschickt.\n\nGanz .....(6)..... davon gilt natürlich deutsches Recht, wenn sich ausländische Unternehmen über deutsche Fernsehkanäle in deutscher Sprache an deutsche Verbraucher .....(7)...... „Teleshoppingkäufe sind im rechtlichen Sinne Fernabsatzverträge, bei denen Verbraucher ein gesetzliches Widerrufs- oder Rückgaberecht von 2 Wochen haben“, sagt die Juristin und ergänzt, „dieses Recht gilt .....(8)..... unbefristet, wenn keine ordnungsgemäße Widerrufs- oder Rückgabebelehrung erfolgt ist.“\n\nDaher rät die Verbraucherzentrale den Verbrauchern, beim Teleshopping .....(9)..... konsequent ihre Rechte durchzusetzen wie bei anderen Verbraucherverträgen auch. .....(10)..... hilft die Verbraucherzentrale Sachsen mit Tipps und Informationen.",
