    "text": "Warum die Klimadebatte Schlafwagen wieder in .....(1)..... bringt.\n\nDer Zug heißt \"Nightjet\", aber .....(2)..... so schnell wie mit dem Flugzeug ist es nicht. Eine Bahnreise von Wien nach Brüssel verursacht nur einen Bruchteil des CO2-Ausstoßes eines Fluges. Bis Dezember soll als 28. Nachtzug-Linie eine von Wien und München nach Amsterdam hinzukommen. \"Wenn wir mehr Schlafwagen hätten, könnten wir das Angebot rasch deutlich .....(3).....\", sagt Bernhard Rieder von der ÖBB. Fünf Jahre dauert es vom Beschluss für einen neuen Zug bis zur Inbetriebnahme, auch weil Aufträge europaweit ausgeschrieben werden müssen. Man könne sie aber inzwischen kostendeckend betreiben. Pro Schlafwagen sei ein \"Night Steward\" an Bord. .....(4)..... seien in der Regel acht Mitarbeiter in einem Nachtzug unterwegs, tagsüber seien es nur zwei - plus die Lokführer. Die Bahn betont, es gebe auch Züge, die in der Nacht fahren, aber mit Sitzplätzen. Wer das mal gemacht hat, kommt gerädert am Zielort an. Am 15. Dezember hat die Bahn in Kooperation mit den ÖBB auf den Strecken Zürich-Berlin und Zürich-Hamburg eine .....(5)..... Intercity-Nachtverbindung gestartet.\n\n\"Daher investieren wir in den kommenden Jahren rund zwölf Milliarden Euro in unsere Fahrzeugflotte, die allein im Fernverkehr auf insgesamt 600 Züge anwachsen wird.\" Dazu sollen auch rund tausend zusätzliche Mitarbeiter .....(6)..... werden. \"Wenn die Deutsche Bahn nicht will, ist das bedauernswert.\" Er sehe aber kein Hindernis, warum nicht .....(7)..... dieses Angebot bei Nachtzügen übernehmen sollten - ihnen dürften nur keine Steine in den Weg gelegt werden. Sie betonen, mit einem Nachtzug gebe es die Chance die vielen Flugreisen, die im Rahmen der Ratspräsidentschaft zwischen Berlin und Brüssel anfallen werden, .....(8)..... ein klimafreundliches Mobilitätsangebot zu reduzieren. Bisher müssten viele das Flugzeug nutzen, weil sie mit den aktuellen Zugverbindungen für Reisen zwischen Berlin und Brüssel nur tagsüber reisen können, damit sechs bis acht Stunden Zeit verlieren und in der Regel einen Tag vorher anreisen müssen. Am liebsten würden sie es sehen, wenn so dieser neue Nachtzug in den blau-gelben Europafarben .....(9)..... wäre. Und der Nachtzug weckt bei vielen Menschen auch die Sehnsucht nach ungewöhnlichen Fernreisen. Der Nachtzug der Deutschen Bahn wurde .....(10)..... damals hoher Verluste 2016 eingestellt.",
