    "text": "Lange sah es so aus, als würde er ganz verschwinden: Die Rede ist vom Nachtzug. In den letzten Jahrzehnten wurde er immer mehr von Billigfliegen verdrängt und viele Angebote wurden .....(1)..... . Noch in den 1990er Jahren fuhren allerdings Nachtzüge von Deutschland aus direkt bis nach Venedig, Stockholm oder Warschau. Heute sind die Österreichischen Bundesbahnen der größte Nachtzuganbieter in Europa. Und das Geschäft läuft: Das Angebot gewinne kontinuierlich neue .....(2)..... , erklärt Sprecher Olaf Heise\n\nDie Zahl der Flugreisen steigt zwar weiter an, aber aus .....(3)..... des Umweltschutzes rücken andere Transportmittel wieder stärker in den Fokus. Kommt der Nachtzug also wieder in .....(4)..... ? Und könnten komfortable Schlafwagen tatsächlich dem Flugzeug als Reisemittel .....(5)..... machen?\n\nStefan Wiese, der als passionierter Bahnfahrer ein Blog für Zugreisende betreibt, ist skeptisch: ,, In den engen Schlafabteilen ist es manchmal .....(6)..... schön ungemütlich und stickig.\" .....(7)..... schrecke die lange Reisezeit viele ab. Mit dem Flugzeug schaffe man es in 90 Minuten von München nach Rom, mit der Bahn brauche man 13 Stunden\n\nDennoch: Es muss nicht immer das Flugzeug sein. .....(8)..... umweltschonendes Transportmittel ist der Nachtzug aktueller denn je. Zumal er auch einige romantische Vorstellungen weckt: Vor den Zugfenstern ziehen malerische Landschaften vorbei, .....(9)..... man von dem sanften Rattern des Zuges in den Schlaf gewiegt wird.\n\nSicher ist jedenfalls: Wer schon bedauert hatte, dass mit dem Verschwinden des Nachtzugs ein Stück Reisekultur verlorengehen könnte, war etwas .....(10)..... . Als sanfte Alternative zum Fliegen hat er durchaus eine Zukunft.",
