    "text": "Jeder Mensch ist anders. Wir alle haben individuelle Charakterzüge, Werte und Interessen. Das schlägt sich auch bei der Wahl unserer Hobbys nieder. .....(1)..... wollen wir unsere Freizeit mit Aktivitäten verbringen, die uns glücklich machen. In der Psychologie geht man von fünf zentralen Charaktereigenschaften aus. .....(2)..... jener Eigenschaften verändern sich die Präferenzen für Hobbys. So liegt es zum Beispiel .....(3)....., dass offene Personen Neues entdecken. Zu gewissenhaften Menschen .....(4)..... am besten Hobbys, die ihre strukturierte Seite .....(5)..... lassen. Für extrovertierte Personen eignen sich .....(6)..... Aktivitäten wie Konzerte oder Feste. Verträgliche Menschen sind gern .....(7)..... engagiert. Zu neurotischen Menschen passen beruhigende Hobbys, die sich ohne Gesellschaft .....(8)..... lassen. Obwohl diese Theorie plausibel erscheint, ist sie .....(9)..... kaum wissenschaftlich untersucht. Jeder Mensch sollte seinen Hobbys nachgehen - .....(10)..... von seinen Charaktermerkmalen.",
