    "text": "Deutsche Sprache, schwere Sprache! Warum heißt es zum Beispiel das Mädchen, wenn Mädchen doch immer weiblich sind? Wieso hat man Angst vor Spinnen und nicht wegen Spinnen? Die Erklärung ist simpel und frustrierend: .....(1).....! Im Laufe der Zeit haben sich durch unseren Sprachgebrauch sprachliche Phänomene etabliert, die heutzutage als willkürlich und unlogisch empfunden werden können. Sprachhistoriker Rüdiger Müllerlein sagt .....(2).....: „In Deutschland gibt es keine Institution, die regelt, was falsch und was richtig ist. Da sich unsere Sprache in einem stetigen Wandel befindet, müssen alle Grammatikbücher, die auf dem Markt sind, deshalb regelmäßig erneuert werden.“\n\nVor allem für Deutschlernende stellt dies eine große Herausforderung dar. Woher .....(3)..... man denn, was richtig und was falsch ist, wenn sich das ständig ändert? Darauf antwortet der Sprachhistoriker: „Derzeit orientiert man sich an der Sprache, die im Rundfunk und im Fernsehen gesprochen wird.“ Für Deutschlernende, die noch .....(4)..... Zeit zu Zeit im Regelschungel herumirren, gibt es aber laut Rüdiger Müllerlein Grund zur Hoffnung: „Da die sozialen Medien das klassische Fernsehen nach und nach verdrängen, passt sich unsere Sprache auch in den anderen Bereichen immer mehr an dieses sogenannte Social-Media-Deutsch .....(5)......“ Die Meinungen über diese Entwicklungen gehen auseinander. So .....(6)..... Kritiker beispielsweise ein verbindliches Regelwerk, in dem Rechtschreibung, Aussprache und Grammatik geregelt sind. Sie sehen diese Veränderungen nämlich als Zeichen des Sprachverfalls. Die Verbindung, die man .....(7)..... der eigenen Kultur hat, könne verloren gehen, wenn viele deutsche Begriffe von englischen Ausdrücken verdrängt werden würden. Rüdiger Müllerlein .....(8)..... von diesem Anliegen wenig: „Im Zeitalter der Globalisierung ergibt es keinen Sinn, eine Sprache konservieren zu wollen. Es gibt zum Beispiel immer wieder neue technische Begriffe, die in den Sprachgebrauch aufgenommen werden müssen, da mitunter die notwendige deutsche .....(9)..... Verfügung stehen.“\n\nSprache ist also ein Spiegel der Gesellschaft und Sprachwandel somit ein natürlicher Prozess, der sich durch ein Regelwerk nicht aufhalten .....(10)......",
